// === Tab: mySketch ===
let skyShader
let blades

function setup() {
  createCanvas(1112, 834, WEBGL)
  skyShader = createShader(vert, frag)

	blades = []
	for (let i = 0; i < 40; i++) {
		const angle = random(TWO_PI)
		const r = random(1, 1.1)
		const x = cos(angle)*r*Math.hypot(width, height)
		const y = sin(angle)*r*Math.hypot(width, height)
		const angleJitter = random(-1,1)*0.2*PI
		blades.push({ x, y, angle, angleJitter })
	}
}

function draw() {
	const time = millis()/1000
	background(0)

	drawingContext.disable(drawingContext.DEPTH_TEST)
  rectMode(CENTER)
  imageMode(CENTER)
  noStroke()
  push()
  shader(skyShader)
	skyShader.setUniform('time', time)
  rect(0, 0, width, height)
  pop()

	drawingContext.enable(drawingContext.DEPTH_TEST)
	push()
	noStroke()
	ambientLight('#93a6ad')
	directionalLight(255, 255, 255, -1, -0.5, 1)

	for (const { x, y, angle, angleJitter } of blades) {
		push()
		translate(x, y, 0)
		rotateZ(angle + PI/2)
		rotateX(-PI/9 + sin(time + 100*angle)*0.08)
		rotateZ(angleJitter)
		specularMaterial('#60ba56')
		shininess(80)
		for (const side of [-1, 1]) {
			beginShape(TRIANGLE_STRIP)
			normal(side, 0.5, 1)
			for (let y = 0; y < 20; y++) {
				for (let x of [side, 0]) {
					vertex(
						x*20*(1-y/20),
						400 + sin(y/20*PI),
						-y*450,
					)
				}
			}
			endShape()
		}
		pop()
	}

	pop()
}

