// === Tab: skyShader ===
// Just a pass-through vertex shader, nothing fancy here
const vert = `attribute vec3 aPosition;
  attribute vec3 aNormal;
  attribute vec2 aTexCoord;

  uniform mat4 uModelViewMatrix;
  uniform mat4 uProjectionMatrix;
  uniform mat3 uNormalMatrix;

  varying highp vec2 vVertTexCoord;

  void main(void) {
    vec4 positionVec4 = vec4(aPosition, 1.0);
    gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
    vVertTexCoord = aTexCoord;
  }
`

const frag = `precision mediump float;
  varying highp vec2 vVertTexCoord;
	uniform float time;

  // Noise functions
  // https://gist.github.com/patriciogonzalezvivo/670c22f3966e662d2f83
  float mod289(float x){return x - floor(x * (1.0 / 289.0)) * 289.0;}
	vec4 mod289(vec4 x){return x - floor(x * (1.0 / 289.0)) * 289.0;}
	vec4 perm(vec4 x){return mod289(((x * 34.0) + 1.0) * x);}

	float noise(vec3 p){
			vec3 a = floor(p);
			vec3 d = p - a;
			d = d * d * (3.0 - 2.0 * d);

			vec4 b = a.xxyy + vec4(0.0, 1.0, 0.0, 1.0);
			vec4 k1 = perm(b.xyxy);
			vec4 k2 = perm(k1.xyxy + b.zzww);

			vec4 c = k2 + a.zzzz;
			vec4 k3 = perm(c);
			vec4 k4 = perm(c + 1.0);

			vec4 o1 = fract(k3 * (1.0 / 41.0));
			vec4 o2 = fract(k4 * (1.0 / 41.0));

			vec4 o3 = o2 * d.z + o1 * (1.0 - d.z);
			vec2 o4 = o3.yw * d.x + o3.xz * (1.0 - d.x);

			return o4.y * d.y + o4.x * (1.0 - d.y);
	}

	float noiseOctaves(vec3 n, int i) {
		float result = 0.;
		for (int j = 0; j < 8; j++) {
			if (j == i) break;
			result += noise(n*pow(2.,float(j)))/pow(2.,float(j));
		}
		return result;
	}

	float map(float value, float min1, float max1, float min2, float max2, bool c) {
		float val = min2 + (value - min1) * (max2 - min2) / (max1 - min1);
		if (c) {
			val = clamp(val, min2, max2);
		}
		return val;
	}

  void main() {
		vec2 coord = gl_FragCoord.xy;

		float noiseVal = noiseOctaves(
			vec3(
				vVertTexCoord*8. + time*vec2(0.1,0.05),
				time*0.07
			),
			4
		);
		vec3 color;
		if (noiseVal < 1.1) {
			color = mix(
				vec3(109., 200., 242.)/255.,
				vec3(1.,1.,1.),
				map(noiseVal, 0.8, 1.1, 0., 1., true)
			);
		} else if (noiseVal < 1.5) {
			color = mix(
				vec3(1.,1.,1.),
				vec3(188., 215., 227.)/255.,
				pow(map(noiseVal, 1.1, 1.5, 0., 1., true), 1.5)
			);
		} else {
			color = mix(
				vec3(188., 215., 227.)/255.,
				vec3(147., 166., 173.)/255.,
				map(noiseVal, 1.5, 2., 0., 1., true)
			);
		}
		gl_FragColor = vec4(color, 1.);

    //gl_FragColor = vec4(mix(dark, light, dithered), 1.);
  }
`

